parameters.jsCode:
const item = $input.first();

const raw = item.json.body ?? item.json;

// NEW OpenAI Responses API path
const msg = raw?.output?.[0]?.content?.[0]?.text;

if (!msg || typeof msg !== 'string') {
  throw new Error('OpenAI: missing message content');
}

let parsed;

try {
  parsed = JSON.parse(msg);
} catch (e) {
  throw new Error('OpenAI: content is not valid JSON');
}
console.log(parsed);

const arr = Array.isArray(parsed) ? parsed : parsed.scenes;

if (!Array.isArray(arr) || arr.length === 0) {
  throw new Error('Scene planner must return a non-empty array');
}

const allowed = new Set(['veo', 'pexels', 'rightplay', 'cta']);

const scenes = [];

for (let i = 0; i < arr.length; i++) {

  const s = arr[i] || {};

  const type = String(s.type || '').toLowerCase();

  if (!allowed.has(type)) {
    throw new Error('Invalid scene type at index ' + i);
  }

  const start = Number(s.start);
  const end = Number(s.end);

  if (
    !Number.isFinite(start) ||
    !Number.isFinite(end) ||
    end <= start
  ) {
    throw new Error('Invalid start/end at index ' + i);
  }

  scenes.push({
    index: i,
    type,
    start,
    end,
    prompt: String(s.prompt ?? ''),
    action: String(s.action ?? ''),
    caption: String(s.caption ?? ''),
    voiceText: String(s.voiceText ?? '')
  });
}

const vin = $('Validate Input').first().json;

const base = {
  script: vin.script,
  product: vin.product,
  skipApprovalHook: vin.skipApprovalHook,
  approveRender: vin.approveRender,
  previewWebhookUrl: vin.previewWebhookUrl,
  receivedAt: vin.receivedAt
};

return scenes.map((sc) => ({
  json: {
    ...base,
    scene: sc
  }
}));

return {
  json: {
    message: $json.message || 'workflow error',
    error: $json
  }
};

