parameters.jsCode:
// ----------------------------------------------------
// Prepare Insert Payload / Flatten Upload Queue
// ----------------------------------------------------

const timeline = $json.timeline || {};
const scenes = Array.isArray(timeline.scenes) ? timeline.scenes : [];

const uploadQueue = [];

// Process chronological tracking rows defensively
for (const scene of scenes) {
    if (!scene) continue;

    const assets = Array.isArray(scene.candidateAssets) ? scene.candidateAssets : [];

    const sceneIndex = scene.index !== undefined ? Number(scene.index) : 0;
    const defaultDuration = Number(scene.duration) || 5;

    const sanitizedCaption = String(scene.caption || "").trim();
    const sanitizedPrompt = String(scene.prompt || "").trim();

    for (const asset of assets) {
        if (!asset || !asset.assetUrl) continue;

        const providerToken = String(asset.provider || "unknown").toLowerCase();
        const fallbackDuration = Number(asset.duration || defaultDuration);

        const uniqueAssetToken = asset.id || `gen_${Math.random().toString(36).substr(2, 5)}`;
        const assetId = `${sceneIndex}_${providerToken}_${uniqueAssetToken}`;

        uploadQueue.push({
            sceneIndex: sceneIndex,
            provider: providerToken,
            assetUrl: asset.assetUrl,
            thumbnail: asset.thumbnail || asset.metadata?.image || asset.metadata?.preview || "",
            duration: isNaN(fallbackDuration) || fallbackDuration <= 0 ? 5 : fallbackDuration,
            caption: sanitizedCaption,
            prompt: sanitizedPrompt,
            assetId: assetId
        });
    }
}

return {
    json: {
        timelineId: timeline.timelineId || `timeline_${Date.now()}`,
        product: timeline.product || "Unknown Product",
        desiredLayout: timeline.desiredLayout || "1080x1920",
        orientation: timeline.orientation || "portrait",
        uploadQueue,
        assetCount: uploadQueue.length
        //scenes:$json.timeline.scenes.type '+' $json.timeline.scenes.prompt || '' ,
    }
};

// ----------------------------------------------------
// Build Canva Design Structure (Scenario A Compliant)
// One page per CANDIDATE ASSET, not per scene
// ----------------------------------------------------
let timeline = $json.timeline || {};

// FIX 1: Robust cascading lookup using '.item' context instead of '.last()'
if (!timeline.scenes || (Array.isArray(timeline.scenes) && timeline.scenes.length === 0)) {
    try {
        timeline = $("Merge With Timeline").item.json.timeline || timeline;
    } catch (e) {}
}
if (!timeline.scenes || (Array.isArray(timeline.scenes) && timeline.scenes.length === 0)) {
    try {
        timeline = $("Build Candidate Timeline JSON1").item.json.timeline || timeline;
    } catch (e) {}
}
if (!timeline.scenes || (Array.isArray(timeline.scenes) && timeline.scenes.length === 0)) {
    try {
        timeline = $("Merge With Timeline").last().json.timeline || timeline;
    } catch (e) {}
}

// FIX 2: Safe handling if timeline.scenes is a single object instead of an array
let scenes = [];
if (timeline.scenes) {
    scenes = Array.isArray(timeline.scenes) ? timeline.scenes : [timeline.scenes];
}

// ----------------------------------------------------
// KEY CHANGE: flatMap scenes -> one page PER candidate asset
// ----------------------------------------------------
const pages = scenes.flatMap((scene, index) => {
    if (!scene) return [];
    const sceneIndex = scene.index !== undefined ? Number(scene.index) : index;

    const candidates = Array.isArray(scene.candidateAssets) && scene.candidateAssets.length > 0
        ? scene.candidateAssets
        : [null]; // scene with no candidates still gets 1 placeholder page

    return candidates.map((asset, candidateIdx) => {
        // Unique key per candidate: matches uploadQueue's assetId format
        // e.g. "0_pexels_pexels_1" (sceneIndex_provider_id)
        const provider = asset?.provider || "unknown";
        const assetLocalId = asset?.id || `noasset${candidateIdx}`;
        const compositeAssetId = `${sceneIndex}_${provider}_${assetLocalId}`;

        return {
            pageId: `page_${compositeAssetId}`,   // UNIQUE per candidate, not per scene
            sceneIndex,
            assetId: compositeAssetId,             // used by Prepare Insert Payload to match
            pageName: `Scene ${sceneIndex + 1} - ${provider}`,
            duration: Number(scene.duration) || 5,
            caption: String(scene.caption || "").trim(),
            voiceText: String(scene.voiceText || "").trim(),
            prompt: String(scene.prompt || "").trim(),
            candidateAsset: asset || null,         // single asset, not an array anymore
            placeholders: {
                video: `VIDEO_${sceneIndex}`,
                caption: `CAPTION_${sceneIndex}`,
                voice: `VOICE_${sceneIndex}`
            }
        };
    });
}).filter(Boolean);

let fallbackProduct = "";
try {
    fallbackProduct = $input.json?.product || "";
} catch (e) {
    fallbackProduct = "";
}

let buildNodeScenes = {};
try {
    buildNodeScenes = $("Build Candidate Timeline JSON1").item.json.timeline.scenes || {};
} catch (e) {}

let buildType = "";
let buildPrompt = "";
if (Array.isArray(buildNodeScenes)) {
    if (buildNodeScenes[0]) {
        buildType = buildNodeScenes[0].type || "";
        buildPrompt = buildNodeScenes[0].prompt || "";
    }
} else {
    buildType = buildNodeScenes.type || "";
    buildPrompt = buildNodeScenes.prompt || "";
}

const canvaDesign = {
    designName: `${timeline.product || $json.product || fallbackProduct || ""} ${buildType} ${buildPrompt} Review`.replace(/\s+/g, ' ').trim(),
    timelineId: timeline.timelineId || `timeline_${Date.now()}`,
    layout: timeline.desiredLayout || $json.layout || "1080x1920",
    orientation: timeline.orientation || "portrait",
    sceneCount: scenes.length,     // still reflects actual scene count
    pageCount: pages.length,       // NEW: total pages = total candidates
    pages: pages
};

return {
    json: {
        timeline: timeline,
        uploadQueue: Array.isArray($json.uploadQueue) ? $json.uploadQueue : [],
        assetCount: $json.assetCount !== undefined ? Number($json.assetCount) : 0,
        canvaDesign: canvaDesign
    }
};

// ----------------------------------------------------
// Build Complete Review Timeline (Canva Ready v4)
// ----------------------------------------------------

const sd = $getWorkflowStaticData('global');

// Recover candidate buffer
const rawScenes = Array.isArray(sd.timelineCandidates)
    ? [...sd.timelineCandidates]
    : [];

// Sort scenes
rawScenes.sort((a, b) => {

    const ia = Number(a.scene?.index ?? a.index ?? 0);
    const ib = Number(b.scene?.index ?? b.index ?? 0);

    return ia - ib;

});

// Product data
let productInput = {};

try {

    productInput = $('Validate Input and Enrich Script With Product Data2')
        .first()
        .json;

}
catch {

    productInput = {};

}

// Timeline ID
const timelineId = `timeline_${$execution.id}_${Date.now()}`;

// Build scene list
const finalScenes = rawScenes.map(candidate => {

    const scene = candidate.scene ?? candidate;

    const candidateAssets = Array.isArray(candidate.candidateAssets)
        ? candidate.candidateAssets
        : [];

    return {

        index: Number(scene.index ?? 0),

        start: Number(scene.start ?? 0),

        end: Number(scene.end ?? 5),

        duration:
            Number(scene.duration) ||
            Math.max(
                1,
                Number(scene.end ?? 5) -
                Number(scene.start ?? 0)
            ),

        type: scene.type ?? "",

        caption: scene.caption ?? "",

        voiceText: scene.voiceText ?? "",

        prompt: scene.prompt ?? "",

        action: scene.action ?? "",

        reviewStatus:
            candidate.reviewStatus ??
            "pending",

        candidateAssets

    };

});

// Build timeline
const timeline = {

    timelineId,

    version: 2,

    createdAt: new Date().toISOString(),

    reviewSession: "pending",

    canvaDesignId: null,

    product: productInput.product ?? "",

    script: productInput.script ?? "",

    desiredLayout:
        productInput.desiredLayout ??
        "Facebook Reels (1080x1920)",

    orientation:
        productInput.orientation ??
        "portrait",

    sceneCount: finalScenes.length,

    scenes: finalScenes

};

console.log(`Timeline contains ${finalScenes.length} scenes.`);

return {

    json: {

        timeline,

        meta: {

            timelineId,

            sceneCount: finalScenes.length,

            reviewReady: true,

            providerSelectionPending: true,

            canvaReady: true

        }

    }

};

