const items = $input.all();
const source = $('Prepare Canva Design Payload').all(); // same item count/order

return items.map((item, i) => {
  const design = item.json.design;
  if (!design?.id) throw new Error("Missing Canva design.id");

  const originalCanvaDesign = source[i]?.json?.canvaDesign ?? {};
  const timeline = source[i]?.json?.timeline ?? {};

  timeline.canvaDesignId = design.id;
  timeline.canvaUrls = {
    edit: design.urls?.edit_url ?? null,
    view: design.urls?.view_url ?? null
  };

  // Merge the Canva API response INTO the original canvaDesign,
  // preserving pages/placeholders/candidateAssets instead of wiping them out
  const mergedCanvaDesign = {
    ...originalCanvaDesign,     // keeps: designName, sceneCount, pages[], etc.
    id: design.id,
    title: design.title,
    owner: design.owner,
    urls: design.urls,
    created_at: design.created_at,
    updated_at: design.updated_at,
    page_count: design.page_count,
    design_types: design.design_types
  };

  return {
    json: {
      ...source[i].json,          // restores timeline, uploadQueue, assetCount
      canvaDesignId: design.id,
      canvaDesign: mergedCanvaDesign,  // now has BOTH pages[] and API metadata
      design,                     // raw API response kept separately, in case needed
      timeline
    }
  };
});

const allItems = $input.all();
const output = [];
for (const it of allItems) {
  const input = it.json;
  if (Array.isArray(input.uploadQueue)) {
    for (const asset of input.uploadQueue) {
      output.push({ json: { ...asset, timeline: input.timeline, design: input.design, canvaDesign: input.canvaDesign, assetCount: input.assetCount } });
    }
  }
}
return output;

const items = $input.all();

return items.map(item => {
  const filename = `${item.json.provider}_${item.json.assetId}.mp4`;
  const uploadMetadata = JSON.stringify({
    name_base64: Buffer.from(filename).toString("base64")
  });
  return {
    json: {
      ...item.json,
      uploadMetadata
    },
    binary: item.binary
  };
});

const items = $input.all();
return items.map(inputItem => {
  const item = { ...inputItem.json };
  // Canva upload response tracking
  const canvaAssetId = item.job?.asset?.id || null;
  item.canvaAssetId = canvaAssetId;
  if (item.timeline?.scenes && item.sceneIndex !== undefined) {
    const scene = item.timeline.scenes[item.sceneIndex];
    if (scene) {
      if (!scene.canvaAssets) {
        scene.canvaAssets = [];
      }
      scene.canvaAssets.push({
        assetId: item.assetId,
        canvaAssetId,
        provider: item.provider,
        assetUrl: item.assetUrl,
        duration: item.duration,
        uploaded: true
      });
    }
  }
  return { json: item };
});

// ----------------------------------------------------
// Asset Candidate Builder - Content Parsing Layer
// ----------------------------------------------------

const input = $json;
const scene = input.scene || {};
const providers = [];

function addProvider(item) {
    if (!item) return;

    // Safely parse out asset URL across alternative formats
    const url =
        item.assetUrl ||
        item.selectedAssetUrl ||
        item.video?.url ||
        item.selectedFile?.link ||
        "";

    if (!url) return;

    // Extract thumbnail correctly from provider metadata fallback branches
    const thumbnail =
        item.thumbnail ||
        item.preview ||
        item.image ||
        item.metadata?.image ||
        "";

    // Calculate duration cleanly with a safe fallback loop window
    const calculatedDuration = Number(
        item.videoDuration ||
        item.metadata?.duration ||
        scene.duration ||
        (Number(scene.end || 5) - Number(scene.start || 0))
    );
    const duration = isNaN(calculatedDuration) || calculatedDuration <= 0 ? 5 : calculatedDuration;

    // DE-BLOAT: Extract ONLY necessary lightweight metadata properties
    const simplifiedMetadata = {
        id: item.metadata?.id || item.id || undefined,
        width: item.selectedFile?.width || item.metadata?.width || undefined,
        height: item.selectedFile?.height || item.metadata?.height || undefined,
        fps: item.selectedFile?.fps || undefined,
        originalUrl: item.metadata?.url || undefined
    };

    providers.push({
        id: `${item.provider || "unknown"}_${providers.length + 1}`,
        provider: item.provider || item.selectedProvider || "unknown",
        assetUrl: url,
        thumbnail: thumbnail,
        metadata: simplifiedMetadata,
        duration: duration,
        score: Number(item.relevanceScore) || 0,
        approved: false
    });
}

// Process primary payload
addProvider(input);

// Handle nested input structures if multiple providers were merged upstream
if (Array.isArray(input.allProviderResults)) {
    for (const p of input.allProviderResults) {
        addProvider(p);
    }
}

// Remove duplicate candidate tracking URLs safely
const seenUrls = new Set();
const uniqueCandidates = providers.filter(p => {
    if (!p.assetUrl || seenUrls.has(p.assetUrl)) return false;
    seenUrls.add(p.assetUrl);
    return true;
});

// REMOVE ALL BLOAT: Return a sanitized structure built directly for insertion
return {
    json: {
        product: input.product || "",
        desiredLayout: input.desiredLayout || "1080x1920",
        receivedAt: input.receivedAt || new Date().toISOString(),
        reviewStatus: "pending",
        sceneStartTime: input.sceneStartTime || null,
        scene: {
            index: scene.index !== undefined ? Number(scene.index) : 0,
            type: scene.type || "unknown",
            start: Number(scene.start) || 0,
            end: Number(scene.end) || 5,
            prompt: scene.prompt || "",
            caption: scene.caption || "",
            voiceText: scene.voiceText || ""
        },
        candidateAssets: uniqueCandidates,
        candidateCount: uniqueCandidates.length,
        selectedAssetUrl: null,
        selectedProvider: null
    }
};

// ----------------------------------------------------
// Append Candidate Scene To Global Timeline Buffer
// ----------------------------------------------------
const sd = $getWorkflowStaticData('global');

// 1. Safe Initialization of the cache buffer
if (!Array.isArray(sd.timelineCandidates)) {
    sd.timelineCandidates = [];
}

const item = $json;

// 2. Extract and guarantee target numeric Scene Index
const currentSceneIndex = item.scene && item.scene.index !== undefined 
    ? Number(item.scene.index) 
    : (item.index !== undefined ? Number(item.index) : 0);

// 3. Strip memory bloat and take a clean deep-clone snapshot to break references
const sceneSnapshot = JSON.parse(JSON.stringify({
    product: item.product || "",
    desiredLayout: item.desiredLayout || "",
    receivedAt: item.receivedAt || "",
    reviewStatus: item.reviewStatus || "pending",
    sceneStartTime: item.sceneStartTime || null,
    scene: {
        index: currentSceneIndex,
        type: item.scene?.type || "unknown",
        start: Number(item.scene?.start) || 0,
        end: Number(item.scene?.end) || 0,
        prompt: item.scene?.prompt || "",
        caption: item.scene?.caption || "",
        voiceText: item.scene?.voiceText || ""
    },
    candidateAssets: item.candidateAssets || [],
    candidateCount: Number(item.candidateCount) || 0,
    selectedAssetUrl: item.selectedAssetUrl || null,
    selectedProvider: item.selectedProvider || null
}));

// 4. Locate an existing scene entry for this index (if any)
const existingIndex = sd.timelineCandidates.findIndex(s => {
    const sIdx = s.scene && s.scene.index !== undefined 
        ? Number(s.scene.index) 
        : (s.index !== undefined ? Number(s.index) : 0);
    return sIdx === currentSceneIndex;
});

if (existingIndex >= 0) {
    // 5a. Scene already exists — MERGE this candidate's assets into it
    // instead of deleting and overwriting the whole scene
    const existing = sd.timelineCandidates[existingIndex];

    const existingAssets = Array.isArray(existing.candidateAssets)
        ? existing.candidateAssets
        : [];
    const incomingAssets = Array.isArray(sceneSnapshot.candidateAssets)
        ? sceneSnapshot.candidateAssets
        : [];

    // Merge candidate asset arrays, avoiding duplicate ids
    const existingIds = new Set(existingAssets.map(a => a.id));
    const mergedAssets = [
        ...existingAssets,
        ...incomingAssets.filter(a => !existingIds.has(a.id))
    ];

    existing.candidateAssets = mergedAssets;
    existing.candidateCount = mergedAssets.length;

    // Refresh scalar fields with latest incoming values
    existing.product = sceneSnapshot.product || existing.product;
    existing.desiredLayout = sceneSnapshot.desiredLayout || existing.desiredLayout;
    existing.receivedAt = sceneSnapshot.receivedAt || existing.receivedAt;
    existing.reviewStatus = sceneSnapshot.reviewStatus || existing.reviewStatus;
    existing.sceneStartTime = sceneSnapshot.sceneStartTime || existing.sceneStartTime;
    existing.scene = sceneSnapshot.scene;
} else {
    // 5b. New scene — push it as-is
    sd.timelineCandidates.push(sceneSnapshot);
}

// 6. Enforce explicit numeric sorting to guarantee absolute sequence integrity
sd.timelineCandidates.sort((a, b) => {
    const idxA = a.scene && a.scene.index !== undefined ? Number(a.scene.index) : Number(a.index || 0);
    const idxB = b.scene && b.scene.index !== undefined ? Number(b.scene.index) : Number(b.index || 0);
    return idxA - idxB;
});

// Telemetry output logging
console.log(`[Static Buffer Sync] Active count: ${sd.timelineCandidates.length} Scenes. Synchronized Scene Index: ${currentSceneIndex}`);

// 7. Return current item with a clean property state forward
return {
    json: {
        ...item,
        bufferedScenes: sd.timelineCandidates.length
    }
};

const c = $json;

return [

{

json:{

designId:$('Select Brand Template').first().json.designId,

pageId:c.pageId,

assetId:c.assetId,

provider:c.provider,

payload:{

type:"video",

asset_id:c.assetId,

position:{

x:0,

y:0

},

size:{

width:1080,

height:1920

}

}

}

}

];

return [{

json:{

designId:$json.designId,

pageId:$json.pageId,

assetId:$json.assetId,

elementId:$json.result.element.id

}

}];

const review = {};

for (const item of items) {

    const d = item.json;

    if (!review[d.sceneIndex]) {

        review[d.sceneIndex] = {

            sceneIndex: d.sceneIndex,

            caption: d.caption,

            designId: d.designId,

            approved: null,

            candidates: []

        };

    }

    review[d.sceneIndex].candidates.push({

        provider: d.provider,

        assetId: d.assetId,

        pageId: d.pageId,

        elementId: d.elementId,

        duration: d.duration,

        status: "pending"

    });

}

return [{
    json: {
        designId: items[0].json.designId,
        createdAt: new Date().toISOString(),
        status: "pending_review",
        scenes: Object.values(review)
    }
}];

// --------------------------------------------
// Select Asset For Each Scene
// --------------------------------------------

const timeline = $json.timeline;

if (!timeline || !Array.isArray(timeline.scenes)) {
	throw new Error("Timeline or scenes not found.");
}

const selectedScenes = timeline.scenes.map(scene => {

	const asset = scene.selectedAsset;

	if (!asset) {
		throw new Error(`Scene ${scene.index} has no selectedAsset.`);
	}

	if (!asset.canvaAssetId) {
		throw new Error(`Scene ${scene.index} selected asset has no canvaAssetId.`);
	}

	return {
		sceneIndex: scene.index,
		sceneNumber: Math.floor(scene.index / 2) + 1,

		start: scene.start,
		end: scene.end,
		duration: scene.duration,

		caption: scene.caption || "",
		voiceText: scene.voiceText || "",
		prompt: scene.prompt || "",
		action: scene.action || "",

		videoAssetId: asset.canvaAssetId,
		assetProvider: asset.provider,
		assetUrl: asset.assetUrl,
		thumbnail: asset.thumbnail
	};
});

return [{
	json: {
		timelineId: timeline.timelineId,
		canvaDesignId: timeline.canvaDesignId,
		layout: timeline.desiredLayout,
		orientation: timeline.orientation,

		sceneCount: selectedScenes.length,

		scenes: selectedScenes
	}
}];

// ----------------------------------------
// Select Brand Template
// ----------------------------------------

const timeline = $input.first().json.timeline;

const layout = (timeline.desiredLayout || "").toLowerCase();

const templates = [
  {
    match: ["1080x1920", "1080×1920"],
    name: "Portrait",
    brandTemplateId: "REPLACE_WITH_PORTRAIT_TEMPLATE_ID"
  },
  {
    match: ["1080x1350", "1080×1350"],
    name: "Portrait Feed",
    brandTemplateId: "REPLACE_WITH_PORTRAIT_FEED_TEMPLATE_ID"
  },
  {
    match: ["1080x1080", "1080×1080"],
    name: "Square",
    brandTemplateId: "REPLACE_WITH_SQUARE_TEMPLATE_ID"
  },
  {
    match: ["1920x1080", "1920×1080"],
    name: "Landscape",
    brandTemplateId: "REPLACE_WITH_LANDSCAPE_TEMPLATE_ID"
  }
];

const selected =
  templates.find(t =>
    t.match.some(size => layout.includes(size))
  ) || templates[0];

timeline.brandTemplate = {
  name: selected.name,
  brandTemplateId: selected.brandTemplateId
};

return [
  {
    json: {
      timeline
    }
