  throw new Error(
    'Output json must be object'
  );
}


return [
  {
    json: output
  }
];

// Auto-accept AI scene picks — passes through the AI Scene Selector output.
// The AI Scene Selector already chose the best provider per scene.
// This node forwards the decision so Accept AI Scene Picks can pass it to the merge.
return {
  json: {
    ...$json,
    reviewedAt   : new Date().toISOString(),
    reviewResult : 'auto_accepted',
    acceptAll    : true
  }
};

// ── VoiceOver Text Validation ─────────────────────────────────────────────────
// Accepts output from HTTP OpenAI Scene Planner6
// Extracts voiceover from each scene (supports both voiceover + voiceText fields)
// Returns combinedVoiceover as a single paragraph

const item = $input.item.json;

// ── 1. Extract raw content from OpenRouter/OpenAI response ─────────────────
let rawContent =
  item?.choices?.[0]?.message?.content ||   // standard OpenAI format
  item?.output?.[0]?.content?.[0]?.text  ||  // newer Responses API format
  item?.body?.choices?.[0]?.message?.content || // wrapped body format
  '';

// ── 2. Guard: no content at all ───────────────────────────────────────────
if (!rawContent || typeof rawContent !== 'string' || !rawContent.trim()) {
  throw new Error('VoiceOver Validation: No content found in LLM response. Keys found: ' + JSON.stringify(Object.keys(item || {})));
}

// ── 3. Clean markdown fences if present ──────────────────────────────────
let cleaned = rawContent
  .replace(/```json/gi, '')
  .replace(/```/gi, '')
  .trim();

// ── 4. Parse JSON ─────────────────────────────────────────────────────────
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    'VoiceOver Validation: Failed to parse JSON.\n' +
    'Parse error: ' + e.message + '\n' +
    'Raw snippet (first 300 chars): ' + rawContent.substring(0, 300)
  );
}

// ── 5. Extract scenes array ───────────────────────────────────────────────
const scenes = Array.isArray(parsed)
  ? parsed
  : Array.isArray(parsed.scenes)
    ? parsed.scenes
    : [];

if (scenes.length === 0) {
  throw new Error('VoiceOver Validation: scenes array is empty or missing. Parsed keys: ' + JSON.stringify(Object.keys(parsed)));
}

// ── 6. Extract voiceover text per scene ───────────────────────────────────
// Supports both field names: voiceover (planner6 output) + voiceText (scene planner5 output)
const sceneVoiceovers = scenes.map((scene, i) => {
  const text =
    (typeof scene.voiceover  === 'string' && scene.voiceover.trim())  ||
    (typeof scene.voiceText  === 'string' && scene.voiceText.trim())  ||
    '';

  if (!text) {
    console.warn(`VoiceOver Validation: scene ${scene.index ?? i} has no voiceover/voiceText — skipping`);
  }

  return {
    index     : scene.index          ?? i,
    voiceover : text,
    tone      : scene.tone           || '',
    estimated : scene.estimatedDuration ?? 0
  };
});

// ── 7. Build combined paragraph ───────────────────────────────────────────
const combinedVoiceover = sceneVoiceovers
  .map(s => s.voiceover)
  .filter(t => t.length > 0)
  .join(' ');

if (!combinedVoiceover) {
  throw new Error('VoiceOver Validation: All scenes had empty voiceover text. Cannot generate audio.');
}

// ── 8. Return ─────────────────────────────────────────────────────────────
return {
  json: {
    combinedVoiceover,
    sceneVoiceovers,          // per-scene breakdown (useful for debugging)
    sceneCount : sceneVoiceovers.length,
    validScenes: sceneVoiceovers.filter(s => s.voiceover).length,
    charCount  : combinedVoiceover.length,
    estimatedTotalDurationSec: sceneVoiceovers.reduce((acc, s) => acc + (s.estimated || 0), 0)
  }
};

// Get timeline
const input = $json.timeline || {};
const scenes = input.scenes || [];

if (!Array.isArray(scenes)) {
  throw new Error('timeline.scenes not found');
}

// Calculate total duration
let totalDuration = 0;

const updatedScenes = scenes.map(scene => {
  const start = Number(scene.start ?? 0);
  const end   = Number(scene.end   ?? 0);

  // Safe duration — minimum 0.5s per scene
  const duration = Math.max(0.5, end - start);

  totalDuration += duration;

  return {
    ...scene,
    duration
  };
});

// Return result
return [
  {
    json: {
      ...$json,

      timeline: {
        ...input,
        scenes: updatedScenes,
        totalDuration
      },

