// ─────────────────────────────────────────────────────────────────────────────
// Pick Best Provider Result (Hybrid Selection, per-scene)
// Ranks by relevance score first, provider tier as tiebreaker.
// Preserves pairedItem for downstream nodes.
//
// IMPORTANT (asset integrity):
// - Never injects an asset URL that isn't actually present in this node's input.
// - The CTA scene never gets its own background asset — it doesn't have one in
//   the input, and it shouldn't. Instead, it now INHERITS the most recent real
//   content scene's asset (processed in scene-index order), so this node's
//   output already shows the CTA scene backed by the actual last video, rather
//   than a null/placeholder. The Creatomate payload builder still does the real
//   work of extending that video's on-screen duration to cover the CTA window —
//   this just keeps this node's own output consistent with that.
// ─────────────────────────────────────────────────────────────────────────────

const all = $input.all();

const validVideoProviders = [
  'veo3', 'veo','envato', 'pexabay', 'pixabay', 'pexels', 'coverr', 'vecteezy', 'smart_fallback'
];

// Base tier used only as a tiebreaker when relevance scores are equal/absent.
// Veo gets a strong fixed bonus since it's generated to spec, not searched.
const priority = {
  veo3: 3, veo: 3,
  pexabay: 1, pixabay: 1, pexels: 1,envato:1, vecteezy: 2, coverr: 2,
  smart_fallback: 0
};

// Pull whichever relevance score field this provider populated.
// Each provider's Map-And-Cache node stores it in a different spot —
// normalize them into one number without touching those nodes.
function getRelevanceScore(j) {
  const provider = String(j.provider || '').toLowerCase();

  if (provider === 'veo3' || provider === 'veo') {
    // AI-generated to the exact prompt — treat as maximally relevant
    return 100;
  }

  return (
    j.relevanceScore ??                     // pexels
    j.pixabayDebug?.score ??                // pexabay
    j.coverrDebug?.selectedScore ??         // coverr
    j.envatoDebug?.selectedScore ??         // envato
    j.vecteezyDebug?.selectedScore ??       // vecteezy
    0
  );
}

// Combined rank: relevance dominates, provider tier only breaks ties
function rankScore(j) {
  const relevance = getRelevanceScore(j);
  const tier = priority[String(j.provider || '').toLowerCase()] ?? 0;
  return relevance * 10 + tier;
}

function hasUsableUrl(j) {
  const url = j.selectedAssetUrl || j.assetUrl || '';
  return typeof url === 'string' && url.startsWith('http');
}

// -----------------------------------------------------------------------------
// Group ORIGINAL ITEMS by scene
// -----------------------------------------------------------------------------

const groups = new Map();

for (let index = 0; index < all.length; index++) {
  const item = all[index];
  const j = item.json;

  const sceneKey = j.scene?.index ?? j.scene?.start ?? `scene_${index}`;

  if (!groups.has(sceneKey)) groups.set(sceneKey, []);
  groups.get(sceneKey).push({ index, item, json: j });
}

// Process scenes in ascending scene-index order so "last real asset seen so
// far" is well-defined by the time we reach the CTA scene (which is normally
// the final scene, but we don't rely on that assumption).
const orderedSceneKeys = Array.from(groups.keys()).sort((a, b) => {
  const na = typeof a === 'number' ? a : parseFloat(a);
  const nb = typeof b === 'number' ? b : parseFloat(b);
  if (Number.isNaN(na) || Number.isNaN(nb)) return String(a).localeCompare(String(b));
  return na - nb;
});

const results = [];
let lastContentAsset = null; // { url, provider } from the most recent real (non-CTA) scene

// -----------------------------------------------------------------------------
// Process each scene
// -----------------------------------------------------------------------------

for (const sceneKey of orderedSceneKeys) {
  const sceneItems = groups.get(sceneKey);

  const ctaEntry = sceneItems.find(({ json }) =>
    json.provider === 'cta_template' ||
    json.provider === 'cta' ||
    json.ctaOverlay ||
    json.scene?.type === 'cta'
  );

  const capturedCtaOverlay = ctaEntry?.json.ctaOverlay ?? null;
  const isCtaScene = !!ctaEntry;

  let bestEntry = null;
  let bestRank = -Infinity;

  // ---------------------------------------------------------------------------
  // Pick highest-RANKED valid provider (relevance + tier), not just tier
  // ---------------------------------------------------------------------------

  for (const entry of sceneItems) {
    const j = entry.json;
    const providerKey = String(j.provider || '').toLowerCase();

    if (validVideoProviders.includes(providerKey) && hasUsableUrl(j)) {
      const rank = rankScore(j);
      if (rank > bestRank) {
        bestRank = rank;
        bestEntry = entry;
      }
    }
  }

  // ---------------------------------------------------------------------------
  // Handle CTA scenes with no valid-provider asset
  // ---------------------------------------------------------------------------

  if (!bestEntry) {
    if (!isCtaScene) {
      throw new Error(`Pick Best: No valid video asset found for scene ${sceneKey}.`);
    }

    // 1. First, check if ANY item in this scene's actual input has a usable
    //    asset URL, regardless of whether its provider is in the whitelist.
    const anyAssetEntry = sceneItems.find(({ json }) => hasUsableUrl(json));

    if (anyAssetEntry) {
      bestEntry = {
        index: anyAssetEntry.index,
        item: anyAssetEntry.item,
        json: {
          ...anyAssetEntry.json,
          provider: anyAssetEntry.json.provider || 'cta_fallback_asset'
        }
      };
    } else if (lastContentAsset) {
      // 2. Nothing of its own — inherit the most recent real content scene's
      //    asset instead of leaving this null. The CTA overlay is meant to sit
      //    in the foreground of that scene's footage anyway.
      bestEntry = {
        index: ctaEntry.index,
        item: ctaEntry.item,
        json: {
          ...ctaEntry.json,
          provider: 'cta_inherited_asset',
          assetUrl: lastContentAsset.url,
          selectedAssetUrl: lastContentAsset.url,
          inheritedFromProvider: lastContentAsset.provider
        }
      };
    } else {
      // 3. Truly nothing available anywhere (no prior content scene either).
      //    Leave asset fields null instead of injecting a fake demo URL.
      bestEntry = {
        index: ctaEntry.index,
        item: ctaEntry.item,
        json: {
          ...ctaEntry.json,
          provider: 'cta_no_asset',
          assetUrl: null,
          selectedAssetUrl: null
        }
      };
    }
  }

  const bestAsset = bestEntry.json;

  // Track the most recent real (non-CTA) scene's asset for future CTA fallback
  if (!isCtaScene) {
    const url = bestAsset.selectedAssetUrl || bestAsset.assetUrl || '';
    if (url) {
      lastContentAsset = { url, provider: bestAsset.provider || '' };
    }
  }

  results.push({
    json: {
      ...bestAsset,
      ctaOverlay: capturedCtaOverlay,
      allProviderResults: sceneItems.map(e => e.json),
      selectedProvider: bestAsset.provider,
      selectedRelevanceScore: getRelevanceScore(bestAsset), // visible in output for debugging
      selectionReason:
        bestAsset.provider === 'cta_no_asset' ? 'no_asset_in_input' :
        bestAsset.provider === 'cta_inherited_asset' ? 'inherited_from_last_scene' :
        'relevance_ranked'
    },
    pairedItem: bestEntry.item.pairedItem ?? { item: bestEntry.index }
  });
}

// -----------------------------------------------------------------------------
// Keep timeline order
// -----------------------------------------------------------------------------

results.sort((a, b) => (a.json.scene?.index ?? 0) - (b.json.scene?.index ?? 0));

return results;

// 1. Handle both modern ($input.all()) and legacy n8n syntax safely
const incomingItems = (typeof $input !== 'undefined' && typeof $input.all === 'function') ? $input.all() : (typeof items !== 'undefined' ? items : []);

// 2. Sort all incoming items sequentially by their scene index to build a reliable timeline order
const sortedItems = [...incomingItems].sort((a, b) => {
  const indexA = a.json?.scene?.index ?? 0;
  const indexB = b.json?.scene?.index ?? 0;
  return indexA - indexB;
});

let currentTimelineTime = 0;

// 3. Process every scene item and synchronize durations to the true asset metadata safely
const updatedItems = sortedItems.map((item) => {
  // Deep clone the item payload to avoid side-effects and guarantee identical structure retention
  const json = JSON.parse(JSON.stringify(item.json));

  // Extract absolute asset duration from multiple native video metadata blocks
  let actualAssetLength = 0;
  const metadata = json.metadata || json.video?.metadata || {};

  if (typeof metadata.duration === 'number') {
    actualAssetLength = metadata.duration;
  } else if (typeof metadata.durationSec === 'number') {
    actualAssetLength = metadata.durationSec;
  } else if (typeof json.duration === 'number') {
    actualAssetLength = json.duration;
  }

  if (json.scene) {
    // Fallback logic if metadata is missing: calculate using original design layout window
    const layoutPlannedDuration = Math.max(0.5, (json.scene.end || 0) - (json.scene.start || 0));
    let finalDuration = actualAssetLength > 0 ? actualAssetLength : layoutPlannedDuration;

    // ── STABILITY GUARD AGAINST RENDER FAILURE ──
    // Every single scene's duration MUST remain between 4 and 12 seconds.
    // Long clips are clamped to preserve your high-density timing constraints.
    if (finalDuration > 12) {
      finalDuration = Math.min(layoutPlannedDuration, 12);
      if (finalDuration < 4) finalDuration = 12; 
    } else if (finalDuration < 4) {
      finalDuration = 4; // Absolute minimum duration constraint floor
    }

    // Recalculate timeline bounds dynamically so scenes blend into one another with zero micro-gaps
    json.scene.start = currentTimelineTime;
    json.scene.end = currentTimelineTime + finalDuration;
    json.scene.duration = finalDuration;

    // Sync any nested rendering configuration profiles to the updated true asset length
    if (json.scene.video) {
      json.scene.video.duration = finalDuration;
    }
    if (json.scene.elementConfig) {
      json.scene.elementConfig.duration = finalDuration;
    }

    // Explicitly guarantee provider-specific queries pass through validation uncorrupted 
    json.scene.searchQuery = json.scene.searchQuery || '';
    json.scene.coverrSearchQuery = json.scene.coverrSearchQuery || '';
    json.scene.vecteezySearchQuery = json.scene.vecteezySearchQuery || '';
    json.scene.envatoSearchQuery = json.scene.envatoSearchQuery || '';

    // Dynamic CTA Sync: Adjust dynamic CTA timing if it falls completely outside shifted scene windows
    const cta = json.ctaOverlay || json.scene.ctaOverlay;
    if (cta && typeof cta.showAtSecond === 'number') {
      if (cta.showAtSecond < json.scene.start || cta.showAtSecond >= json.scene.end) {
        cta.showAtSecond = Math.max(json.scene.start, json.scene.end - 4);
      }
    }

    // CRITICAL FIX: Update nested provider snapshots/cache blocks to eliminate inner timing conflicts
    if (Array.isArray(json.allProviderResults)) {
      json.allProviderResults.forEach((providerRes) => {
        if (providerRes.scene) {
          providerRes.scene.start = json.scene.start;
          providerRes.scene.end = json.scene.end;
          providerRes.scene.duration = finalDuration;
        }
      });
    }

    // Advance the timeline clock to the clean edge of this asset
    currentTimelineTime = json.scene.end;
  }

  return { json };
});

return updatedItems;

