}

let parsed;

try {
  let cleaned = msg
    .replace(/```json/gi, '')
    .replace(/```/gi, '')
    .trim();

  // Escape newlines inside JSON string values
  cleaned = cleaned.replace(/"([^"\\]|\\.)*"/g, (match) => {
    return match
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '\\r');
  });

  cleaned = cleaned
    .replace(/,\s*\}/g, '}')
    .replace(/,\s*\]/g, ']');

  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('OpenAI: content is not valid JSON\n\n' + e.message);
}

const arr = Array.isArray(parsed) ? parsed : parsed.scenes;

