// FIXED: Added missing comma between 'vecteezy' and 'pexabay'
const allowed = new Set(['veo','envato', 'pexels', 'coverr', 'vecteezy', 'pexabay', 'cta']);

const scenes = [];

for (let i = 0; i < arr.length; i++) {
