const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.timelineScenes)) sd.timelineScenes = [];

const scene = $json.scene || {};
const sceneIdx = typeof scene.index === 'number' ? scene.index : parseInt(scene.index ?? '0', 10);

// Calculate the intended scene duration dynamically based on the script boundaries
const duration = Math.max(0.5, ((scene.end || 1) - (scene.start || 0)) || 1);

// Capture CTA Overlay: Prioritize explicit property, then scene object, then legacy template
const ctaOverlay = $json.ctaOverlay || scene.ctaOverlay || null;

// Enhanced Asset Extraction Logic
const getAssetUrl = () => {
  // 1. Explicitly check for Pixabay metadata structure
  if ($json.metadata?.videos?.large?.url) return $json.metadata.videos.large.url;
  // 2. Fallback to existing asset paths
  return $json.assetUrl || $json.selectedAssetUrl || $json.videoUrl || $json.url || '';
};

const entry = {
  index              : sceneIdx,
  type               : scene.type || 'unknown',
  start              : scene.start || 0,
  end                : scene.end || duration,
  duration           : duration,
  caption            : scene.caption || '',
  voiceText          : scene.voiceText || '',
  prompt             : scene.prompt || '',
  action             : scene.action || '',
  desiredLayout      : $json.desiredLayout || scene.desiredLayout || '',

  // Preserving explicit provider queries safely within the buffered trace
  searchQuery        : scene.searchQuery || '',
  coverrSearchQuery  : scene.coverrSearchQuery || '',
  vecteezySearchQuery: scene.vecteezySearchQuery || '',

  // Standard RenderScript properties at the root level for fallback mapping
  source             : getAssetUrl(),
  loop               : true,
  fit                : 'cover',

  // Preserve CTA overlay
  ctaOverlay: ctaOverlay,

  video: {
    url      : getAssetUrl(),
    source   : getAssetUrl(), // Standard Creatomate property name
    provider : $json.provider || '',
    metadata : $json.metadata || {},
    duration : duration,      // Dynamically locks element duration to scene duration
