const existingIdx = sd.timelineScenes.findIndex(s => s.index === sceneIdx);
if (existingIdx >= 0) {
  const existing = sd.timelineScenes[existingIdx];
  // Preserve CTA if the new update doesn't have one but existing did
  if (existing.ctaOverlay && !entry.ctaOverlay) {
    entry.ctaOverlay = existing.ctaOverlay;
  }
  sd.timelineScenes[existingIdx] = entry;
} else {
  sd.timelineScenes.push(entry);
}

// Keep timeline sorted by scene index
sd.timelineScenes.sort((a, b) => (a.index ?? 0) - (b.index ?? 0));

// ── Dynamic Timeline Continuity Recalculation ───────────────────────────────
// Automatically forces the timeline to be perfectly contiguous with zero time gaps
let currentTimelineTime = 0;
sd.timelineScenes.forEach(s => {
  s.start = currentTimelineTime;
  s.end = currentTimelineTime + s.duration;
  if (s.video) {
