  }
  currentTimelineTime = s.end;
});

// ── Legacy CTA Auto-Assignment ──────────────────────────────────────────────
const hasCTAOverlay = sd.timelineScenes.some(s => s.ctaOverlay);
const hasOldCTAScene = sd.timelineScenes.some(s => s.type === 'cta');

if (!hasCTAOverlay && hasOldCTAScene) {
