// ── Inputs ────────────────────────────────────────────────────────────────────
const base          = $('Attach Scene Context').first().json;
const body          = $json.body ?? $json;
const videos        = body?.videos ?? [];

// ── Scene context ─────────────────────────────────────────────────────────────
const sceneIndex    = base?.scene?.index    ?? 0;
const scenePrompt   = (base?.scene?.prompt  || '').toLowerCase();
const sceneType     = (base?.scene?.type    || '').toLowerCase();
const sceneAction   = (base?.scene?.action  || '').toLowerCase();
const sceneDuration = (base?.scene?.end ?? 5) - (base?.scene?.start ?? 0);
const scriptText    = (base?.script         || '').toLowerCase();
const contextWords  = `${scenePrompt} ${sceneType} ${sceneAction} ${scriptText}`;

// ── Dynamic Orientation & Aspect Inference ────────────────────────────────────
const layout = (base?.desiredLayout || '').toLowerCase();
const orient = (base?.Orientation   || '').toLowerCase();

let targetOrientation = 'landscape'; // Default safe fallback

// 1. LANDSCAPE MATCHING
if (
  orient.includes('landscape') || 
  orient.includes('horizontal') ||
  layout.includes('youtube videos') || 
  layout.includes('video ads') || 
  layout.includes('landscape video') || 
  layout.includes('x video') ||
  layout.includes('16:9') || 
  layout.includes('1920x1080')
) {
  targetOrientation = 'landscape';
} 
// 2. SQUARE MATCHING
else if (
  orient.includes('square') || 
  layout.includes('feed square') || 
  layout.includes('square video') || 
  layout.includes('profile photo') || 
  layout.includes('720x720') ||
  layout.includes('1:1') || 
  layout.includes('1080x1080')
) {
  targetOrientation = 'square';
} 
// 3. PORTRAIT MATCHING
else if (
  orient.includes('portrait') || 
  orient.includes('vertical') ||
  layout.includes('reels') || 
  layout.includes('stories') || 
  layout.includes('shorts') || 
  layout.includes('vertical video') || 
  layout.includes('tiktok') || 
  layout.includes('feed portrait') || 
  layout.includes('instagram') || 
  layout.includes('9:16') || 
  layout.includes('1080x1350') || 
  layout.includes('1080x1920')
) {
  targetOrientation = 'portrait';
}

// ── Global dedup state ────────────────────────────────────────────────────────
const sd = $getWorkflowStaticData('global');
if (!sd.pexelsCache)     sd.pexelsCache     = {};
if (!sd.usedVideoIds)    sd.usedVideoIds    = [];
if (!sd.usedVideoJobKey) sd.usedVideoJobKey = '';

// Reset per render job
const jobKey = base?.receivedAt || '';
if (sd.usedVideoJobKey !== jobKey) {
  sd.usedVideoJobKey = jobKey;
  sd.usedVideoIds    = [];
}

// ── Relevance scorer 
function scoreVideo(v) {
  if (!v) return 0;

  // Extract filename keywords from image URL (most signal-rich field)
  const imageFilename = (v.image || '').split('/').pop().split('?')[0]
    .replace(/[-_\d]/g, ' ').toLowerCase();

  // Also parse video URL slug
  const urlSlug = (v.url || '').split('/').filter(Boolean).pop()
    ?.replace(/-/g, ' ') || '';

  const haystack = [
    imageFilename,
    urlSlug,
    (v.user?.name || '')
  ].join(' ').toLowerCase();

  const words = contextWords.split(/\s+/).filter(w => w.length > 3);

  // Weighted: URL slug match = 2pts, others = 1pt
  return words.reduce((acc, w) => {
    const inSlug     = urlSlug.includes(w)      ? 2 : 0;
    const inHaystack = haystack.includes(w)     ? 1 : 0;
    return acc + Math.max(inSlug, inHaystack);
  }, 0);
}

// ── Dynamic Layout-Adaptive File Selector ──────────────────────────────────────
function pickBestFile(files = []) {
  if (!files || files.length === 0) return null;

  // CRITICAL FILTER: Keep only High Definition (HD) and Ultra High Definition (UHD) files
  const premiumQualityFiles = files.filter(f => {
    const q = (f.quality || '').toLowerCase();
    return q === 'hd' || q === 'uhd';
  });

  // Fallback to original list only if no HD/UHD assets exist at all
  const filteredFiles = premiumQualityFiles.length > 0 ? premiumQualityFiles : files;

  const scoredFiles = filteredFiles.map(f => {
    let score = 0;
    const w = f.width || 0;
    const h = f.height || 0;
    const q = (f.quality || '').toLowerCase();

    // 1. Dynamic Structural Matching
    if (targetOrientation === 'portrait' && h > w) {
      score += 1000;
    } else if (targetOrientation === 'landscape' && w > h) {
      score += 1000;
    } else if (targetOrientation === 'square') {
      if (Math.abs(w - h) <= (w * 0.15)) {
        score += 1000; // Perfect square match
      } else if (h > w) {
        score += 500;  // Portrait assets clip into square frames better than landscape
      }
    }

    // 2. Stream Resolution Preference
    if (q === 'hd') {
      score += 200;
      if (targetOrientation === 'landscape' && w >= 1920) score += 50;
      if (targetOrientation === 'portrait' && h >= 1920) score += 50;
    } else if (q === 'uhd') {
      score += 150; // Ultra high-def is clear but carries network performance overhead
    }

    return { file: f, score };
  });

  // Sort descending by calculated matching score
  scoredFiles.sort((a, b) => b.score - a.score);
  return scoredFiles[0]?.file || null;
}

// ── Score + filter candidates ─────────────────────────────────────────────────
const eligible = videos.filter(v =>
  v?.id &&
  !sd.usedVideoIds.includes(v.id) &&
  (v.duration || 0) >= Math.max(sceneDuration - 1, 3)
);

// If all used, fall back to full list (avoid fallback video)
const pool = eligible.length > 0 ? eligible : videos;

// Sort by score DESC — use sceneIndex as tiebreaker offset
const sorted = pool
  .map(v => ({ v, score: scoreVideo(v) }))
  .sort((a, b) => b.score - a.score);

// Pick at offset = sceneIndex % pool size — guarantees different video per scene
// just take the best-scoring, not-yet-used candidate
const bestVid = sorted[0]?.v || null;
//const bestVid   = sorted[pickIndex]?.v || sorted[0]?.v || null;
const bestFile  = pickBestFile(bestVid?.video_files ?? []);
let   assetUrl  = bestFile?.link || '';
let   meta      = bestVid || {};
const ok        = !!assetUrl;

// ── Dynamic Layout-Aware Fallback ─────────────────────────────────────────────
if (!ok) {
  if (targetOrientation === 'landscape') {
    assetUrl = 'https://videos.pexels.com/video-files/3045163/3045163-hd_1920_1080_30fps.mp4';
  } else {
    // Dynamic Portrait / Square fallback clip asset
    assetUrl = 'https://videos.pexels.com/video-files/4458249/4458249-hd_1080_1920_25fps.mp4';
  }
  meta = { ...meta, fallback: true, reason: !videos.length ? 'no_videos_returned' : 'no_valid_file_found' };

// ── Cache + mark used ─────────────────────────────────────────────────────────
} else {
  if (bestVid?.id) sd.usedVideoIds.push(bestVid.id);
  try {
    const key = $('Pexels Cache Read Write1').first().json?.pexelsCacheKey;
    if (key) sd.pexelsCache[key] = { assetUrl, metadata: meta };
  } catch (e) {
    meta = { ...meta, cacheWriteError: e.message };
  }
}

// ── Output ────────────────────────────────────────────────────────────────────
return {
  json: {
    ...base,
    provider             : 'pexels',
    fromCache            : false,
    fromSheet            : false,
    assetUrl,
    selectedFile         : bestFile ?? null,
    ctaOverlay           : base.scene?.ctaOverlay ?? null, 
    totalResults         : body?.total_results ?? 0,
    videosConsidered     : videos.length,
    eligibleVideos       : eligible.length,
   // pickedAtIndex        : pickIndex,
    relevanceScore       : scoreVideo(bestVid),
    inferredOrientation  : targetOrientation,
    usedVideoIdsCount    : sd.usedVideoIds.length,
    metadata             : meta
  }
};

// CTA Template Asset — Pure Metadata Provider
const base = $('Attach Scene Context').first().json;
const scene = base.scene || {};

const ctaData = {
  headline   : scene.caption || 'Get Started Today',
  subheadline: scene.voiceText || '',
  buttonText : 'Install from Zoho Marketplace',
  logo       : 'https://res.cloudinary.com/dpxjnwibk/image/upload/v1781596647/Untitled_design_hcydoc.png',
  website    : base.marketplace_url || 'https://marketplace.zoho.com/vendor/zenith-innovations',
  product    : base.product || '',
