const base  = $('Attach Scene Context').first().json;
const scene = base.scene || {};

const prompt = (scene.prompt || '').toLowerCase();
const type   = scene.type || 'unknown';

const rows = $('Sheet Lookup Before Providers').all();

// ── 1. DETECT TARGET LAYOUT & ORIENTATION ────────────────────────────────────
const targetLayout = (base.desiredLayout || '').toLowerCase();
const targetOrientation = (base.Orientation || base.orientation || '').toLowerCase();

// Flags vertical formats like Portrait, 9:16, 4:5, Instagram, TikTok, Shorts, Reels
const isTargetVertical = targetOrientation.includes('portrait') || 
                         targetOrientation.includes('vertical') || 
                         targetLayout.includes('instagram') || 
                         targetLayout.includes('tiktok') || 
                         targetLayout.includes('shorts') || 
                         targetLayout.includes('reels') || 
                         targetLayout.includes('1080x1920') || 
                         targetLayout.includes('1080x1350') ||
                         targetLayout.includes('9:16') ||
                         targetLayout.includes('4:5');

// ── 2. SCORE & FILTER ROWS WITH ORIENTATION AWARENESS ────────────────────────
function scoreRow(row) {
  const r = row.json;

  // Determine asset orientation from sheet columns
  const assetOrientation = (r.orientation || r.layout || '').toLowerCase();
  let isAssetVertical = false;

  if (assetOrientation) {
    isAssetVertical = assetOrientation.includes('portrait') || 
                      assetOrientation.includes('vertical') || 
                      assetOrientation.includes('9:16');
  } else if (Number(r.width) && Number(r.height)) {
    isAssetVertical = Number(r.height) > Number(r.width);
  } else if (r.asset_url) {
    // Structural fallback: extract resolution patterns directly from asset URLs
    const urlLower = r.asset_url.toLowerCase();
    if (urlLower.includes('1080_1920') || urlLower.includes('1080x1920') || urlLower.includes('portrait') || urlLower.includes('vertical')) {
      isAssetVertical = true;
    }
  }

  // STRATIFIED ORIENTATION FILTER:
  // If layouts do not match, heavily penalize the row so it doesn't pollute correct aspect ratio assets
  if (isTargetVertical !== isAssetVertical) {
    return -100; 
  }

  const tags      = (r.tags || '').toLowerCase();
  const prompt2   = (r.prompt || '').toLowerCase();
  const sceneType = (r.scene_type || '').toLowerCase();

  let score = 0;

  // Scene type match (bonus)
  if (sceneType === type.toLowerCase()) {
    score += 5;
  }

  // Keyword matching loop
  const words = prompt.split(' ');
  for (const w of words) {
    if (w.length < 4) continue;

    if (tags.includes(w)) {
      score += 3;
    }

    if (prompt2.includes(w)) {
      score += 2;
    }
  }

  return score;
}

let best = null;
let bestScore = -1;

for (const row of rows) {
  const score = scoreRow(row);

  if (score > bestScore) {
    bestScore = score;
    best = row.json;
  }
}

let assetUrl = '';

// Improved — require at least some similarity before using the match
if (best && best.asset_url && bestScore >= 2) {
  assetUrl = best.asset_url;
} else {
  // ── 3. DYNAMIC ORIENTATION FALLBACKS (EMERGENCY LAST RESORT) ────────────────
  // Swaps out the emergency generic asset depending on vertical vs horizontal output target
  assetUrl = isTargetVertical
    ? 'https://videos.pexels.com/video-files/4761428/4761428-hd_1080_1920_24fps.mp4' // True Vertical 9:16 Fallback Video
    : 'https://res.cloudinary.com/dm0vso3aa/video/upload/v1779363199/hvsi6kqvtshds8blks3k.mp4'; // Original Horizontal Video
}

return {
  json: {
    ...base,
    scene,
    assetUrl,
    // Propagate ctaOverlay so it is not lost in fallback
    ctaOverlay: base.scene?.ctaOverlay ?? null, 
    provider: 'smart_fallback',
    fromCache: true,
    fromSheet: false,
    processingLog: {
      usedFallback: true,
      providerFailed: true,
      fallbackReason: 'providers_failed_reused_library_asset',
      targetIsVertical: isTargetVertical
    },
    metadata: {
      originalType: type,
      reusedAsset: !!best && bestScore >= 2,
      matchedScene: (best && bestScore >= 2) ? best.prompt : 'None (Used Emergency Aspect Fallback)'
    }
  }
};

