// ── Sheet Lookup with Scored Cache Match ──────────────────────────────────────
const sd = $getWorkflowStaticData('global');

// Load sheet rows into in-memory cache once per run
const jobKey = $json.receivedAt || '';
if (sd.sheetCacheJobKey !== jobKey || !sd.sheetRowsCache) {
  sd.sheetCacheJobKey = jobKey;
  sd.sheetRowsCache   = [];
  try {
    const all = $('Sheet Lookup Before Providers1_raw1').all();
    sd.sheetRowsCache = all.map(r => r.json).filter(r => r.asset_url && r.asset_url.startsWith('http'));
    console.log('Sheet cache loaded:', sd.sheetRowsCache.length, 'rows');
  } catch(e) {
    console.warn('Sheet read failed, skipping cache:', e.message);
  }
}

const scene     = $json.scene || {};
const sceneType = (scene.type   || '').toLowerCase().trim();
const prompt    = (scene.prompt || '').toLowerCase().trim();
const action    = (scene.action || '').toLowerCase().trim();   // ← single declaration
const caption   = (scene.caption|| '').toLowerCase().trim();
const combined  = `${sceneType} ${prompt} ${action} ${caption}`;

// Build fingerprint
const currentFingerprint = sceneType + '||' + prompt.slice(0,80) + '||' + action.slice(0,40);

// ── 1. Exact / Fingerprint match = instant cache hit ─────────────────────────
const exactMatch = (sd.sheetRowsCache || []).find(r => {
  if (r.scene_fingerprint) {
    return r.scene_fingerprint === currentFingerprint;
  }
  // Fallback for older rows without fingerprint column
  return r.prompt &&
         r.prompt.toLowerCase() === prompt &&
         r.scene_type &&
         r.scene_type.toLowerCase() === sceneType;
});

if (exactMatch) {
  console.log('Sheet cache EXACT HIT — fingerprint:', currentFingerprint, 'url:', exactMatch.asset_url);
  return {
    json: {
      ...$json,
      fromSheet : true,
      fromCache : true,
      provider  : exactMatch.provider || 'sheet_cache',
      assetUrl  : exactMatch.asset_url,
      metadata  : { source: 'google_sheet', cacheScore: 999, matchedPrompt: exactMatch.prompt }
    }
  };
}

// ── 2. Scored keyword match ───────────────────────────────────────────────────
let best = null;
let bestScore = 0;

for (const row of (sd.sheetRowsCache || [])) {
  const rowType        = (row.scene_type        || '').toLowerCase();
  const rowTags        = (row.tags              || '').toLowerCase();
  const rowPrompt      = (row.prompt            || '').toLowerCase();
  const rowFingerprint = (row.scene_fingerprint || '').toLowerCase();
  let score = 0;

  // Type match is mandatory
  if (rowType !== sceneType) continue;

  // Fingerprint bonus — if fingerprint matches, force this as best
  if (rowFingerprint && rowFingerprint === currentFingerprint) {
    score += 20;
  }

  // Keyword scoring
  const words = combined.split(/\s+/).filter(w => w.length > 3);
  for (const w of words) {
    if (rowTags.includes(w))   score += 3;
    if (rowPrompt.includes(w)) score += 2;
  }

  if (score > bestScore) { bestScore = score; best = row; }
}

// Require at least 5 points to use scored cache
if (best && bestScore >= 5) {
  console.log('Sheet cache SCORED HIT — score:', bestScore, 'provider:', best.provider, 'url:', best.asset_url);
  return {
    json: {
      ...$json,
      fromSheet : true,
      fromCache : true,
      provider  : best.provider || 'sheet_cache',
      assetUrl  : best.asset_url,
      metadata  : { source: 'google_sheet', cacheScore: bestScore, matchedPrompt: best.prompt }
    }
  };
}

// ── 3. No match — proceed to providers ───────────────────────────────────────
console.log('Sheet cache MISS — sceneType:', sceneType, '— proceeding to providers');
return { json: { ...$json, fromSheet: false, fromCache: false } };

const scene = $json.scene;
if (!scene) throw new Error('Attach Scene Context: missing scene payload');

// Store current scene in global static data for lookups
const sd = $getWorkflowStaticData('global');
sd.currentSceneCtx = { ...$json };

console.log(`Attach Scene Context: scene ${scene.index} type=${scene.type} ctaOverlay=${!!scene.ctaOverlay}`);

return {
  json: {
    ...$json,
    type: scene.type,
    // Explicitly pass ctaOverlay forward
    ctaOverlay: scene.ctaOverlay || null, 
    sceneStartTime: Date.now()
  }
};

const base = $('Attach Scene Context').first().json;
const statusCode = $json.statusCode ?? $json.status;
const body = $json.body ?? $json;
const ok = !body?.error && (statusCode === 200 || statusCode === 201);
let assetUrl = body?.secure_url || body?.url || '';

let meta = body?.metadata || body || {};

if (!ok || !assetUrl) {
  const sd = $getWorkflowStaticData('global');
  // Prompt-scored fallback library
  const prompt = (base?.scene?.prompt || '').toLowerCase();
  const fallbackLibrary = [
    { tags: ['dashboard','crm','software','screen','interface','saas'], url: 'https://videos.pexels.com/video-files/8512857/8512857-hd_1920_1080_30fps.mp4' },
    { tags: ['office','laptop','computer','work','desk','typing'],      url: 'https://videos.pexels.com/video-files/10375454/10375454-hd_1920_1080_30fps.mp4' },
    { tags: ['meeting','team','conference','presentation','business'],  url: 'https://videos.pexels.com/video-files/3252000/3252000-hd_1920_1080_25fps.mp4' },
    { tags: ['sales','lead','outreach','email','contact','campaign'],   url: 'https://videos.pexels.com/video-files/6984650/6984650-hd_1920_1080_25fps.mp4' },
  ];
  let bestUrl = 'https://videos.pexels.com/video-files/3045163/3045163-hd_1920_1080_30fps.mp4';
  let bestScore = -1;
  for (const item of fallbackLibrary) {
    const score = item.tags.filter(t => prompt.includes(t)).length;
    if (score > bestScore) { bestScore = score; bestUrl = item.url; }
  }
  assetUrl = bestUrl;
  meta = { ...meta, fallback: true, reason: 'veo_failed', statusCode };
} else {
  const sd = $getWorkflowStaticData('global');
  const key = $('VEO Dedupe Cache1').first().json?.veoCacheKey;
  if (!sd.veoPromptCache) sd.veoPromptCache = {};
  if (key) sd.veoPromptCache[key] = { assetUrl, metadata: meta };
}

return {
  json: {
    ...base,
    provider: 'veo3',
    fromCache: false,
    fromSheet: false,
    assetUrl,
    metadata: meta
  }
};

