parameters.jsCode:
// ── Inputs ────────────────────────────────────────────────────────────────────
const base = $('Attach Scene Context').first().json;
const body = $json.body ?? $json;
const videos = Array.isArray(body?.hits) ? body.hits : []; 

console.log(`Pixabay response: ${videos.length} videos, totalHits: ${body?.totalHits}`);

// ── Scene context ─────────────────────────────────────────────────────────────
const sceneIndex    = base?.scene?.index ?? 0;
const scenePrompt   = (base?.scene?.prompt || '').toLowerCase();
const sceneAction   = (base?.scene?.action || '').toLowerCase();
const sceneDuration = (base?.scene?.end ?? 5) - (base?.scene?.start ?? 0);
const scriptText    = (base?.script || '').toLowerCase();

// Concatenate for scoring
const contextWords = `${scenePrompt} ${sceneAction} ${scriptText}`;

// ── Dynamic Orientation Filter (Updated) ──────────────────────────────────────
let nodeLayout = '';
try {
  // Directly pull the requested layout configurations from the designated cache node
  nodeLayout = $('Pexabay Cache Read Write').item.json.desiredLayout;
} catch (e) {
  try {
    // Graceful fallback option if n8n multi-item execution structures differ
    nodeLayout = $('Pexabay Cache Read Write').first().json.desiredLayout;
  } catch (err) {}
}

const layout = (nodeLayout || base?.desiredLayout || '').toLowerCase();
const orient = (base?.Orientation || '').toLowerCase();

let targetOrientation = 'landscape';
if (orient.includes('landscape') || layout.includes('1920x1080') || layout.includes('youtube')) {
  targetOrientation = 'landscape';
} else if (orient.includes('square') || layout.includes('1080x1080')) {
  targetOrientation = 'square';
} else if (orient.includes('portrait') || layout.includes('1080x1920') || layout.includes('reels') || layout.includes('tiktok') || layout.includes('shorts')) {
  targetOrientation = 'portrait';
}

// Helper to determine a raw video hit's true layout orientation 
function getVideoOrientation(v) {
  if (!v || !v.videos) return 'unknown';
  const f = v.videos.large || v.videos.medium || v.videos.small;
  if (!f) return 'unknown';
  if (f.width > f.height) return 'landscape';
  if (f.height > f.width) return 'portrait';
  return 'square';
}

// ── Global Dedup State ────────────────────────────────────────────────────────
const sd = $getWorkflowStaticData('global');
if (!sd.pixabayCache) sd.pixabayCache = {};
if (!sd.usedPixabayIds) sd.usedPixabayIds = [];
if (!sd.usedPixabayJobKey) sd.usedPixabayJobKey = '';

const jobKey = base?.receivedAt || '';
if (sd.usedPixabayJobKey !== jobKey) {
  sd.usedPixabayJobKey = jobKey;
  sd.usedPixabayIds = [];
}

// ── Scoring Logic ─────────────────────────────────────────────────────────────
function scoreVideo(v) {

    if (!v) return 0;

    const haystack = [
        v.tags,
        v.user,
        v.type
    ]
    .join(' ')
    .toLowerCase();

    let score = 0;

    const keywords = contextWords
        .split(/\s+/)
        .filter(w => w.length > 2);

    const unique = [...new Set(keywords)];

    for (const word of unique) {

        if (haystack.includes(word))
            score += 2;

    }

    // Bonus for business-related footage
    if (/business|office|computer|technology|team|meeting|laptop/.test(haystack))
        score += 1;

    return score;
}

// ── Pick Best Video Resolution ──────────────────────────────────────────────────
function pickBestVideo(v) {
  if (!v || !v.videos) return null;

  const variants = [];
  ['large', 'medium', 'small'].forEach(q => {
    if (v.videos[q]?.url) {
      variants.push({
        url: v.videos[q].url,
        width: v.videos[q].width || 0,
        height: v.videos[q].height || 0,
        quality: q
      });
    }
  });

  if (!variants.length) return null;

  const scored = variants.map(f => {
    let score = 0;
    // Orientation matching
    if (targetOrientation === 'portrait' && f.height > f.width) score += 1000;
    else if (targetOrientation === 'landscape' && f.width > f.height) score += 1000;
    else if (targetOrientation === 'square' && Math.abs(f.width - f.height) < 100) score += 1000;

    // Quality preference
    score += (f.quality === 'large' ? 300 : f.quality === 'medium' ? 200 : 100);
    return { file: f, score };
  });

  return scored.sort((a, b) => b.score - a.score)[0]?.file || null;
}

// ── Filter and Select (Layout Filtering Added Here) ───────────────────────────
// Step 1: Base eligibility filter (ID deduplication & duration limits)
// ───────────────────────────────────────────────────────────────
// SMART RELEVANCE + ORIENTATION SELECTION
// ───────────────────────────────────────────────────────────────

// Base eligibility
// ── Smart Candidate Selection ───────────────────────────────────────────────

// Base eligibility
const eligible = videos.filter(v =>
  v?.id &&
  !sd.usedPixabayIds.includes(v.id) &&
  (v.duration || 0) >= 2
);

const basePool = eligible.length ? eligible : videos;

// Nothing returned
if (!basePool.length) {
  return {
    json: {
      ...base,
      provider: 'pixabay',
      assetUrl: '',
      metadata: null,
      noResult: true,
      pixabayDebug: {
        reason: 'No videos returned',
        totalHits: body?.totalHits || 0
      }
    }
  };
}

// Score every candidate
const scoredPool = basePool.map(v => ({
  video: v,
  score: scoreVideo(v),
  orientation: getVideoOrientation(v)
}));

// Highest relevance score
const maxScore = Math.max(...scoredPool.map(x => x.score), 0);

// Keep only videos reasonably close to the best score
let relevancePool = scoredPool.filter(x =>
  x.score >= Math.max(2, maxScore - 1)
);

// If nothing passes the threshold, keep the top few anyway
if (!relevancePool.length) {
  relevancePool = scoredPool
    .sort((a, b) => b.score - a.score)
    .slice(0, 10);
}

// Prefer matching orientation
const orientationPool = relevancePool.filter(
  x => x.orientation === targetOrientation
);

const finalPool =
  orientationPool.length > 0
    ? orientationPool
    : relevancePool;

// Final ranking
finalPool.sort((a, b) => {

  if (b.score !== a.score)
    return b.score - a.score;

  if ((b.video.likes || 0) !== (a.video.likes || 0))
    return (b.video.likes || 0) - (a.video.likes || 0);

  if ((b.video.views || 0) !== (a.video.views || 0))
    return (b.video.views || 0) - (a.video.views || 0);

  return (b.video.downloads || 0) - (a.video.downloads || 0);

});

const bestVid = finalPool[0]?.video || null;
const bestFile = pickBestVideo(bestVid);

//const pickIndex = sceneIndex % (sorted.length || 1);
//const bestVid = sorted[pickIndex]?.v || sorted[0]?.v || null;
// just take the best-scoring, not-yet-used candidate

// ── Final Result Handling ─────────────────────────────────────────────────────
let assetUrl = bestFile?.url || '';
let meta = bestVid || {};

if (!assetUrl) {
  assetUrl = (targetOrientation === 'portrait') 
    ? 'https://videos.pexels.com/video-files/4458249/4458249-hd_1080_1920_25fps.mp4' 
    : 'https://videos.pexels.com/video-files/3045163/3045163-hd_1920_1080_30fps.mp4';
} else {
  if (bestVid?.id) sd.usedPixabayIds.push(bestVid.id);
  // Cache Write
  const key = base?.pixabayCacheKey;
  if (key) sd.pixabayCache[key] = { assetUrl, metadata: meta };
}

return {
  json: {
    ...base,
    provider: 'pixabay',
    assetUrl,
    metadata: meta,
    pixabayDebug: {
