    targetOrientation = 'portrait';
    targetAspectRatio = '9:16';
  } else if (orient.includes('square') || routerLayout.includes('1080x1080')) {
    targetOrientation = 'square';
    targetAspectRatio = '1:1';
  } else if (orient.includes('landscape') || routerLayout.includes('1920x1080') || routerLayout.includes('youtube')) {
    targetOrientation = 'landscape';
    targetAspectRatio = '16:9';
  }
}

function getVideoOrientation(v) {
  const dims = getVideoDimensions(v);
  if (!dims) return 'unknown';
  const { width, height } = dims;
  if (width > height) return 'landscape';
  if (height > width) return 'portrait';
  return 'square';
}

function getVideoAspectRatio(v) {
  const dims = getVideoDimensions(v);
  if (!dims) return null;
  return calculateAspectRatio(dims.width, dims.height);
}

// ── Initialize Static Data Cache ──────────────────────────────────

const sd = $getWorkflowStaticData('global');
if (!sd.envatoCache) sd.envatoCache = {};
if (!sd.usedEnvatoIds) sd.usedEnvatoIds = [];
if (!sd.usedEnvatoJobKey) sd.usedEnvatoJobKey = '';

// Reset used IDs on new job
if (base?.receivedAt !== sd.usedEnvatoJobKey) {
  sd.usedEnvatoJobKey = base?.receivedAt || '';
  sd.usedEnvatoIds = [];
}

function scoreVideo(v) {
  if (!v) return 0;
  const tagStr = Array.isArray(v.tags) ? v.tags.join(' ') : '';
  const haystack = `${tagStr} ${v.name || ''} ${v.description || ''}`.toLowerCase();
  if (!haystack) return 0;

  return contextWords.split(/\s+/)
    .filter(w => w && w.length > 3)
    .reduce((acc, w) => acc + (haystack.includes(w) ? 1 : 0), 0);
}

// ── Multi-Level Filtering Strategy ──────────────────────────────────

// Level 0: Remove used videos
const eligible = videos.filter(v => v?.id && !sd.usedEnvatoIds.includes(v.id));
const basePool = eligible.length > 0 ? eligible : videos;

let pool = basePool;
let filterLevel = 'base';

// Level 1: Filter by aspect ratio (STRICT)
if (targetAspectRatio && basePool.length > 0) {
  const normalized = targetAspectRatio.toLowerCase();
  const aspectMatched = basePool.filter(v => {
    const videoAspectRatio = getVideoAspectRatio(v);
    if (!videoAspectRatio) return false;
    return videoAspectRatio === normalized;
  });

  if (aspectMatched.length > 0) {
    pool = aspectMatched;
    filterLevel = 'aspect-ratio';
  }
}

// Level 2: Filter by orientation (MEDIUM)
if (pool.length === 0 && basePool.length > 0) {
  const orientationMatched = basePool.filter(v => {
    const videoOrientation = getVideoOrientation(v);
    return videoOrientation === 'unknown' || videoOrientation === targetOrientation;
  });

  if (orientationMatched.length > 0) {
    pool = orientationMatched;
    filterLevel = 'orientation';
  }
}

// Level 3: Use full basePool (FALLBACK)
if (pool.length === 0) {
  pool = basePool;
  filterLevel = 'fallback-base';
}

// ── Select best video from pool ──────────────────────────────────

const sorted = pool.map(v => ({
  v,
  score: scoreVideo(v)
})).sort((a, b) => b.score - a.score);

const bestVid = sorted.length > 0
  ? sorted[sceneIndex % sorted.length]?.v || sorted[0]?.v
  : null;

const assetUrl = bestVid?.previews?.icon_with_video_preview?.video_preview_download_url
  || bestVid?.previews?.icon_with_video_preview?.video_url
  || '';

// ── ERROR LOOP TRIGGER ────────────────────────────────────────────

if (!assetUrl || !bestVid) {
  const errorPayload = {
    status: "failed",
    provider: "envato",
    reason: "No video asset found",
    targetOrientation,
    targetAspectRatio,
    desiredLayout: routerLayout,
    filterLevel,
    videoCounts: {
      total: videos.length,
      basePool: basePool.length,
      currentPool: pool.length,
      sorted: sorted.length
    },
    bestVid: bestVid ? {
      name: bestVid.name,
      id: bestVid.id,
      aspectRatio: getVideoAspectRatio(bestVid),
      orientation: getVideoOrientation(bestVid)
    } : null,
    context: base
  };
  throw new Error(JSON.stringify(errorPayload));
}

// ── SUCCESS ROUTING ───────────────────────────────────────────────

if (bestVid?.id) sd.usedEnvatoIds.push(bestVid.id);

const key = base?.envatoCacheKey || base?.scene?.searchQuery;
if (key) sd.envatoCache[key] = { assetUrl, metadata: bestVid };

return {
  json: {
    ...base,
    provider: 'envato',
    assetUrl,
    metadata: bestVid,
    envatoDebug: {
      selectedScore: scoreVideo(bestVid),
      selectedOrientation: getVideoOrientation(bestVid),
      selectedAspectRatio: getVideoAspectRatio(bestVid),
      filterLevel,
      poolSize: pool.length,
      totalVideos: videos.length,
      targetOrientation,
      targetAspectRatio
    }
  }
};

const sd = $getWorkflowStaticData('global');
if (!sd.envatoCache) sd.envatoCache = {};

const action = ($json.scene?.action || $json.scene?.prompt || '').trim();
const key = 'px:' + action;

if (sd.envatoCache[key]) {
  return {
    json: {
      ...$json,
      provider: 'envato',
      fromCache: true,
      assetUrl: sd.envatoCache[key].assetUrl,
      metadata: sd.envatoCache[key].metadata || {}
    }
  };
}

return { json: { ...$json, provider: 'envato', fromCache: false, envatoCacheKey: key, envatoAction: action } };
